#!/bin/sh
# Executable contract for the repositories generated by check_counterexamples.sh.
set -eu
action=$1 repo=$2 rev=$3 file=$4 mode=$5
test "$file" = draw.c
if test -n "${JOV_CASE_CALLS:-}"; then printf '%s %s %s\n' "$action" "$rev" "$mode" >> "$JOV_CASE_CALLS"; fi
test "${JOV_CASE_FAIL:-}" != "$action"
if test "$action" = expect; then
    test "$#" -eq 8
    rule=$(git --no-replace-objects -C "$repo" show "$rev:$6" | sed -n "${7},${8}p")
    case "$rule" in
        'draw must call scan then paint at both modes, 0 and 1.') printf '{"metric":"sequence","required":["scan","paint"]}\n' ;;
        'draw must call paint then scan at both modes, 0 and 1.') printf '{"metric":"sequence","required":["paint","scan"]}\n' ;;
        'draw must call paint exactly twice.') printf '{"metric":"count","target":"paint","required":2}\n' ;;
        *) exit 1 ;;
    esac
    exit
fi
test "$action" = observe && test "$#" -eq 5
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT HUP INT TERM
git --no-replace-objects -C "$repo" show "$rev:$file" > "$work/body.c"
cat > "$work/driver.c" <<'C'
#include <stdio.h>
#include <stdlib.h>
static const char *comma = "";
static void call(const char *s) { printf("%s\"%s\"",comma,s); comma = ","; }
void scan(void) { call("scan"); }
void paint(void) { call("paint"); }
void draw(int);
int main(int argc, char **argv) {
    if (argc != 2) return 1;
    putchar('['); draw((int)strtol(argv[1],NULL,10)); puts("]");
    return 0;
}
C
"${CC:-cc}" "$work/driver.c" "$work/body.c" -o "$work/observe"
"$work/observe" "$mode"
